from kvparse import parse_kv


def test_parse_kv_coerces_scalars():
    assert parse_kv("host=localhost;port=8080;debug=true") == {
        "host": "localhost",
        "port": 8080,
        "debug": True,
    }


def test_parse_kv_ignores_empty_segments_and_whitespace():
    assert parse_kv("  a = 1 ; ; b=2 ") == {"a": 1, "b": 2}


def test_parse_kv_edge_cases():
    assert parse_kv("") == {}
    assert parse_kv("x=1.5") == {"x": 1.5}
    assert parse_kv("flag=false") == {"flag": False}
